// Carriers through both adapters (C10): where each policy goes, what a combination that cannot be written does,
// and payloads whose model cannot carry a suffix.

import omp from "../../omp/src/index.ts";
import pi from "../../pi/src/index.ts";
import { scenarios, type Adapter, type Scenario, type Step } from "./fake-harness.ts";
import type { Expected } from "./wire.ts";

const ADAPTERS: readonly Adapter[] = [
  { name: "omp", register: omp, headerHook: false },
  { name: "pi", register: pi, headerHook: true },
];

/** Each API named, one request each, with `payload`. */
const overApis = (apis: readonly string[], payload: Readonly<Record<string, unknown>>): Step[] =>
  apis.flatMap((api): Step[] => [{ do: "set", model: { api } }, { do: "request", payload }]);

const URL_APIS = ["google-generative-ai", "google-vertex", "google-gemini-cli", "bedrock-converse-stream"];
